mapper.update:
UPDATE performance_issue
SET source_repo_id = #{sourceRepoId},
    source_file_id = #{sourceFileId},
    line_start = #{lineStart},
    line_end = #{lineEnd}
WHERE id = #{id}

UPDATE performance_issue
SET verify_json = #{verifyJson},
    verify_time = #{verifyTime},
    status = #{status}
WHERE id = #{id}

mapper.select:
SELECT 
FROM performance_issue


        app_name = #{appName}


        AND issue_type = #{issueType}


        AND status = #{status}


ORDER BY create_time DESC
LIMIT #{limit}
